    $("#cf").onsubmit = (e) => { e.preventDefault(); run(async () => { const o = id ? { id } : {}; sc.fields.forEach((f) => { const els = $$(`[name="${f.k}"]`, e.target); if (f.t === "images" || f.t === "image") o[f.k] = F.imgs[f.k]; else if (f.t === "check") o[f.k] = els[0].checked; else if (f.t === "multi") o[f.k] = els.filter((x) => x.checked).map((x) => x.value); else if (f.t === "number") o[f.k] = latin(els[0].value); else if (f.t === "datetime") o[f.k] = els[0].value ? new Date(els[0].value).toISOString() : ""; else o[f.k] = els[0].value; }); await api("upsert", { coll, item: o }); await refreshStore(); closeModal(); toast("ذخیره شد", "ok"); VIEWS[A.view]($("#view")); }); };
